/* Numera Academy — Desenho da página, foco, cliques e teclado; por último, abre a página pedida no endereço.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Renderização e eventos ---------- */
const TITLES={treino:'Treino',home:'Início',academy:'Trilhas',cases:'Missões',case:'Missão',jogos:'Jogos',lab:'Terminal',review:'Revisão',progress:'Progresso'};
function focusMode(){return s.page==='course'&&s.tab!=='learn'||s.page==='case'||s.page==='review'&&s.reviewId&&P.ids.has(s.reviewId);}
// Depois de redesenhar, o foco volta ao "mesmo" controle (mesmo id ou mesma ação), ou ao alvo pedido pela tela.
function focusKey(el){if(!el||!el.getAttribute)return null;if(el.id&&el.id!=='main')return '#'+el.id;const act=el.getAttribute('data-act');if(!act)return null;let sel=`[data-act="${act}"]`;for(const k of ['data-id','data-index','data-page'])if(el.getAttribute(k)!==null)sel+=`[${k}="${String(el.getAttribute(k)).replace(/"/g,'')}"]`;return sel;}
function restoreFocus(key){try{const want=focusAfter||key;focusAfter=null;if(!want)return;const el=document.querySelector(want);if(el&&el.focus)el.focus({preventScroll:!!key&&want===key});}catch(_){}}
// Expoentes de verdade em todo texto da página (v10.1): x^3 → x³ (em <sup>), e^(−x) → e com −x elevado, 10^-6 → 10⁻⁶.
// Só mexe no texto entre as tags: atributos, a <textarea> da equação (o teclado cuida dela) e os desenhos SVG ficam como estão.
// "Use x, ^, parênteses" continua com o ^, porque ali não há base nem expoente: é o nome da tecla.
function supText(t){let out='',i=0;
 while(i<t.length){
  if(t[i]==='^'&&i>0&&/[\w)\]}²³π.]/.test(t[i-1])){const j=i+1;
   if(t[j]==='('||t[j]==='{'){const open=t[j],close=open==='('?')':'}';let d=0,k=j;for(;k<t.length;k++){if(t[k]===open)d++;else if(t[k]===close&&--d===0)break;}
    if(k<t.length){out+='<sup>'+supText(t.slice(j+1,k)).replace(/-/g,'−')+'</sup>';i=k+1;continue;}}
   const m=/^[+\-−]?(?:\d+(?:[.,]\d+)?|[a-zA-Zπ])/.exec(t.slice(j));
   if(m){out+='<sup>'+m[0].replace('-','−')+'</sup>';i=j+m[0].length;continue;}}
  out+=t[i];i++;}
 return out;}
function supHtml(html){if(html.indexOf('^')<0)return html;let skip=0;
 return html.split(/(<[^>]*>)/).map(part=>{if(part.charAt(0)==='<'){const m=/^<(\/?)(textarea|svg)\b/i.exec(part);if(m&&!/\/>$/.test(part))skip=Math.max(0,skip+(m[1]?-1:1));return part;}
  return skip>0||part.indexOf('^')<0?part:supText(part);}).join('');}
function render(){const pages={home,academy,course,cases,case:casePage,jogos,lab,progress,review,treino:()=>TR?TR.page():''};let fkey=null;try{fkey=focusKey(document.activeElement);}catch(_){}if(!pages[s.page])s.page='home';document.title='Numera Academy · '+(s.page==='course'?method(s.method).title:TITLES[s.page]);const focus=focusMode();const notice=s.warning?`<div class="wrap"><div class="notice" role="status"><span>${safe(s.warning)}</span>${btn('Fechar','dismiss','text')}</div></div>`:'';
 $('#app').innerHTML=supHtml(focus?`<div class="app-shell focus"><main id="main" tabindex="-1" class="page-${s.page==='case'?'case-page':s.page}">${notice}${pages[s.page]()}</main></div>`:`<div class="app-shell">${topbar()}<main id="main" tabindex="-1" class="page-${s.page}">${notice}${pages[s.page]()}</main>${footer()}${mobileNav()}</div>`);
 restoreFocus(fkey);
 if(s.page==='home')startAuto();else stopAuto();
 mascots();}
// O casal aparece só onde há desafio: prática da trilha, missão e revisão ativa.
const mascotOn=()=>(s.page==='course'&&s.tab==='practice')||s.page==='case'||(s.page==='review'&&!!s.reviewId&&P.ids.has(s.reviewId));
function mascots(){const MZ=window.NumeraMascotes;if(!MZ)return;try{MZ.update({visible:mascotOn(),outfit:p.outfit||[]});if(s.mascot){const r=s.mascot;s.mascot=null;MZ.react(r.kind,{coins:r.coins});}}catch(_){}}
function openCourse(id){s.method=id;s.q=nextQ(id);s.tab='learn';s.sim=0;s.introStep=0;s.pathSel=null;navigate('course');}
function startNode(key){if(key!=='intro'&&key!=='sim'&&!worldOpen(s.method)){s.pathSel=key;render();return;}if(key==='intro'){s.tab='intro';s.introStep=0;}else if(key==='sim'){s.tab='simulate';s.sim=0;}else{const i=Number(key.slice(1));if(i>nextQ(s.method)&&!p.completed[`c:${s.method}:${i}`])return;s.q=i;s.tab='practice';}resetQuestion();s.pathSel=null;render();window.scrollTo({top:0,behavior:'auto'});}
const raf=window.requestAnimationFrame?window.requestAnimationFrame.bind(window):(fn=>setTimeout(fn,16));let dragging=false,queued=false;
function demoFromPointer(e){const svg=$('.demo-svg.draggable');if(!svg)return;const box=svg.getBoundingClientRect();if(!box.width)return;const vx=(e.clientX-box.left)/box.width*G.W,x=G.lo+(vx-G.L)/(G.W-G.L-G.R)*(G.hi-G.lo);setNewtonX(x);s.demos.newton.k=0;if(!queued){queued=true;raf(()=>{queued=false;refreshDemo();});}}
document.addEventListener('pointerdown',e=>{if(e.target.closest&&e.target.closest('#hero-widget'))stopAuto();if(e.target.closest&&e.target.closest('.demo-svg.draggable')){dragging=true;e.preventDefault();demoFromPointer(e);}});
document.addEventListener('pointermove',e=>{if(dragging)demoFromPointer(e);});
document.addEventListener('pointerup',()=>{dragging=false;});
document.addEventListener('pointercancel',()=>{dragging=false;});
document.addEventListener('submit',e=>{if(e.target.id==='quiz-form'){e.preventDefault();answerQuestion();}if(e.target.id==='terminal-form'){e.preventDefault();solve();}if(e.target.id==='guide-form'){e.preventDefault();checkGuide();}if(e.target.id==='tr-form'){e.preventDefault();if(TR)TR.submit();}if(e.target.id==='tr-pv-form'){e.preventDefault();if(TR&&TR.handle(TR.examActive()?'tr-pv-next':'',{dataset:{}}))render();}});
document.addEventListener('input',e=>{const id=e.target.id;if(['source','a','b','x0','x1','g','min','max','tolerance','maxIterations','initial','answer','guideAnswer'].includes(id))s[id]=e.target.value;if(id==='demo-x0'){stopAuto();setNewtonX(Number(e.target.value));s.demos.newton.k=0;refreshDemo();}});
document.addEventListener('change',async e=>{if(e.target.id==='g'&&window.NumeraCalc){const v=window.NumeraCalc.toPretty(e.target.value);if(v!==e.target.value){e.target.value=v;s.g=v;}} /* g(x): ao sair do campo, o ^ vira expoente elevado, como na equação */if(e.target.id==='sim-range'){s.sim=Number(e.target.value);render();}if(e.target.id==='algorithm'){collect();render();}if(e.target.id==='restore'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Backup maior que 1 MB não é aceito.');s.pendingRestore=readBackup(JSON.parse(await file.text()));s.confirm='restore';}catch(err){s.warning=err.message;}e.target.value='';render();}});
document.addEventListener('keydown',e=>{if(e.target.id==='source'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();solve();}if(e.key==='Escape'&&focusMode()){if(s.page==='course'){s.tab='learn';render();}else if(s.page==='case')navigate('cases');else{s.reviewId=null;render();}}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const act=el.dataset.act,id=el.dataset.id,index=Number(el.dataset.index);if(act.startsWith('tr-')){if(TR&&TR.handle(act,el))render();return;}if(s.page==='lab')collect();if(act==='nav'){s.reviewId=null;navigate(el.dataset.page);return;}if(act==='course'){openCourse(id);return;}if(act==='case'){s.caseId=id;s.caseQ=Math.max(0,C.CASES.find(c=>c.id===id).tasks.findIndex((_,i)=>!p.completed[`p:${id}:${i}`]));navigate('case');return;}
 if(act==='demo'){stopAuto();s.demo=id;const w=$('#hero-widget');if(w)w.innerHTML=heroWidget();return;}
 if(act==='demo-step'){stopAuto();demoStep();refreshDemo();return;}
 if(act==='demo-reset'){stopAuto();demoReset();const w=$('#hero-widget');if(w)w.innerHTML=heroWidget();return;}
 if(act==='node'){s.pathSel=id;render();return;}
 if(act==='start-node'){startNode(id);return;}
 if(act==='intro-next'){const n=introScreens().length;if(s.introStep<n-1)s.introStep++;else{markVisited(`${s.method}:intro`);s.tab='simulate';s.sim=0;}render();window.scrollTo({top:0,behavior:'auto'});return;}
 if(act==='intro-prev'){s.introStep=Math.max(0,s.introStep-1);render();return;}
 if(act==='video-toggle'){s.videoOpen=s.videoOpen===id?null:id;render();return;}
 if(act==='sim-done'){markVisited(`${s.method}:sim`);if(worldOpen(s.method)){s.q=nextQ(s.method);s.tab='practice';}else{s.tab='learn';s.pathSel='t0';}resetQuestion();render();window.scrollTo({top:0,behavior:'auto'});return;}
 if(act==='feat')s.featTab=id;else if(act==='topics')s.topicsTab=id;
 else if(act==='course-tab'){s.tab=id;s.sim=0;s.pathSel=null;resetQuestion();}else if(act==='lesson'){if(index>nextQ(s.method)&&!p.completed[`c:${s.method}:${index}`])return;s.q=index;resetQuestion();}else if(act==='select'){s.selected=index;s.feedback=null;}else if(act==='hint'){s.hint=true;P.wrong(p,currentId());persist();}else if(act==='next-course'){if(s.q<11){s.q++;resetQuestion();}else{s.tab='learn';resetQuestion();}}else if(act==='next-case'){if(s.caseQ<2){s.caseQ++;resetQuestion();}else{navigate('cases');return;}}else if(act==='sim-next')s.sim++;else if(act==='sim-prev')s.sim=Math.max(0,s.sim-1);else if(act==='example'){clearInputs();s.source=EXAMPLES[index][1];s.mode=s.source.includes('\n')?'system':'root';s.algorithm='auto';s.result=null;s.error='';}else if(act==='case-terminal'){const c=C.CASES.find(c=>c.id===s.caseId);clearInputs();s.source=c.expression;s.mode=s.source.includes('\n')?'system':'root';s.algorithm='auto';if(c.terminal)Object.assign(s,c.terminal);s.result=null;s.error='';navigate('lab');return;}else if(act==='mode'){clearInputs();s.mode=id;s.algorithm='auto';s.source=id==='system'?'2x+y=5\nx+3y=6':'x^3-x-2=0';s.result=null;s.error='';}else if(act==='help')s.help=!s.help;else if(act==='history')s.historyOpen=!s.historyOpen;else if(act==='history-load'){clearInputs();s.source=p.history[index].source;s.mode=s.source.includes('\n')||s.source.includes('|')?'system':'root';s.algorithm='auto';s.result=null;s.historyOpen=false;}else if(act==='result-tab')s.resultTab=id;else if(act==='slides-eps')s.slidesEps=Number(id);else if(act==='slides-crit')s.slidesCrit=id;else if(act==='slides-piv')s.slidesPiv=id;else if(act==='free-toggle'){p.free=!p.free;persist();announce(p.free?'Modo livre ligado: todos os mundos abertos.':'Modo livre desligado: os mundos voltam a abrir em ordem.');}else if(act==='buy'){const it=(window.NumeraMascotes?window.NumeraMascotes.ITEMS:[]).find(x=>x.id===id);if(it&&!(p.owned||[]).includes(it.id)&&(p.coins||0)>=it.price){p.coins-=it.price;p.owned=[...(p.owned||[]),it.id];p.outfit=[...(p.outfit||[]),it.id];persist();announce(`${it.name} comprado e vestido. Restam ${p.coins} moedas.`);}}else if(act==='equip'){const on=p.outfit||[];p.outfit=on.includes(id)?on.filter(x=>x!==id):[...on,id];persist();}else if(act==='interval-clear'){s.a='';s.b='';focusAfter='#a';}else if(act==='use-interval'){s.a=ivField(el.dataset.a);s.b=ivField(el.dataset.b);for(const k of ['a','b']){const f=$('#'+k);if(f)f.value=s[k];} /* solve() relê os campos da página */s.error='';s.errorFix=null;focusAfter='#solve-btn';solve();return;}else if(act==='root'){const r=s.result;s.result={...r,...r.roots[index],roots:r.roots,source:r.source,search:r.search,recommendation:r.recommendation,note:r.note,effectiveTolerance:r.effectiveTolerance};s.guideIndex=0;s.guideAnswer='';s.guideFeedback=null;}else if(act==='guide-next'){s.guideIndex++;s.guideAnswer='';s.guideFeedback=null;}else if(act==='guide-reset'){s.guideIndex=0;s.guideAnswer='';s.guideFeedback=null;}else if(act==='review-start'){s.reviewId=id;resetQuestion();}else if(act==='review-close')s.reviewId=null;else if(act==='review-next'){s.reviewId=due().find(i=>i!==s.reviewId)||null;resetQuestion();}else if(act==='backup'){download('numera-backup-completo.json',JSON.stringify(backupEnvelope(),null,2),'application/json');announce('Backup exportado: trilhas, Treino, provas e revisões.');return;}else if(act==='reset'){s.confirm='reset';}else if(act==='confirm-yes'){if(s.confirm==='reset'){p=P.fresh();if(persist())s.warning='Progresso das trilhas reiniciado.';}else if(s.confirm==='restore'&&s.pendingRestore){const b=s.pendingRestore;p=b.trilhas;let ok=persist();if(b.full){if(TR)ok=TR.importState(b.treino)&&ok;visited=b.visitas||{};try{storage.setItem(VISITED_KEY,JSON.stringify(visited));}catch(_){ok=false;}}if(ok)s.warning=b.full?'Backup importado: trilhas, Treino, provas e revisões.':'Backup antigo importado: só as trilhas (arquivos anteriores à v10 não traziam o Treino).';else s.warning='O backup foi carregado nesta aba, mas o navegador não deixou gravar: ao fechar, ele se perde. Libere espaço ou saia da navegação privada e importe de novo.';}s.confirm=null;s.pendingRestore=null;}else if(act==='confirm-no'){s.confirm=null;s.pendingRestore=null;}else if(act==='export-result'){exportResult();return;}else if(act==='export-csv'){exportResult(true);return;}else if(act==='dismiss')s.warning='';else if(act==='install'&&installEvt){const ev=installEvt;ev.prompt();Promise.resolve(ev.userChoice).finally(()=>{installEvt=null;render();});return;}render();});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home',false));
/* PWA: o navegador avisa quando o site pode ser instalado; o botão aparece no rodapé. */
let installEvt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvt=e;render();});window.addEventListener('appinstalled',()=>{installEvt=null;render();});
s.page=(()=>{if(location.hash==='#arena')try{history.replaceState(null,'','#jogos');}catch(_){}const h=location.hash.slice(1)==='arena'?'jogos':location.hash.slice(1);return ['home','academy','cases','jogos','treino','lab','progress','review'].includes(h)?h:'home';})();render();
/* Testes automáticos (tests/verify.cjs) ligam esta bandeira para enxergar o estado interno. */
if(window.__NUMERA_TESTE__)window.__test={s,TR,getP:()=>p,render,navigate,solve,answerQuestion,simulationResult,openCourse,graph,parseAnswer,question,guideTasks,checkGuide,backupEnvelope,readBackup,persist,introScreens,labResult,verification,rootStatus,supHtml,supText,worldOpen,calcSummary,qdSummary,mascotOn,startNode,setP:v=>{p=v;},camarim};
